package store

import (
	"context"
	"encoding/json"
	"os"
	"testing"
	"time"

	"github.com/zeptop-dev/bosun/pkg/agentproto"
	"github.com/zeptop-dev/captain/internal/domain"
	"github.com/zeptop-dev/captain/internal/testdb"
)

// The optional input is generated by bosun's real TLS observer and driver
// continuity tracker. Preserve its proof fields rather than constructing a
// second mock contract that could agree with the panel's own mistake.
func TestFallbackAddressBosunWireContract(t *testing.T) {
	path := os.Getenv("BOSUN_FALLBACK_CONTRACT_FILE")
	if path == "" {
		t.Skip("set BOSUN_FALLBACK_CONTRACT_FILE to the bosun TLS/driver fixture")
	}
	raw, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	var reports []agentproto.Report
	if err := json.Unmarshal(raw, &reports); err != nil || len(reports) != 5 {
		t.Fatalf("expected five driver reports: length=%d err=%v", len(reports), err)
	}
	ctx := context.Background()
	s := New(testdb.Open(t))
	n := &domain.Node{Name: "restricted-network", PublicAddr: "192.0.2.10"}
	must := func(err error) {
		t.Helper()
		if err != nil {
			t.Fatal(err)
		}
	}
	must(s.CreateNodeWithAddressPolicy(ctx, n, "wire-contract-pair", time.Hour, true, false))
	_, err = s.RedeemPairCode(ctx, "wire-contract-pair", "wire-contract-token", "example", "development", "linux")
	must(err)
	base := time.Now().Truncate(time.Second)
	enabled := true
	must(s.setAddressFollowPolicyAt(ctx, n.ID, true, false, &enabled, nil, base.Add(-time.Second)))
	if reports[0].PublicAddresses == nil {
		t.Fatal("first driver report omitted public addresses")
	}
	shift := base.Unix() - reports[0].PublicAddresses.SampledAt
	var firstRun string
	var lastAddress string
	for i, report := range reports {
		sample := report.PublicAddresses
		if sample == nil || sample.FallbackIPv4 == nil || sample.IPv4 != "" {
			t.Fatalf("report %d lacks fallback-only evidence", i)
		}
		// Shift the whole agent clock only. Do not rewrite its intervals, source,
		// conflict assessment or continuity identity.
		sample.SampledAt += shift
		for _, fallback := range []*agentproto.PublicAddressFallback{sample.FallbackIPv4, sample.FallbackIPv6} {
			if fallback != nil {
				fallback.SampledAt += shift
			}
		}
		at := time.Unix(sample.SampledAt, 0)
		must(s.ObserveNodeAddresses(ctx, n.ID, "wire-contract-token", sample, at))
		got, pending, err := s.ReconcileNodeAddresses(ctx, n.ID, at)
		must(err)
		view, err := s.NodeAddresses(ctx, n.ID)
		must(err)
		if view.Observed.IPv4.Address != "" || view.Observed.IPv4.ConfirmedAt != 0 {
			t.Fatal("single-source evidence was promoted into the old dual-source fields")
		}
		switch i {
		case 0:
			firstRun = sample.FallbackIPv4.RunID
			if firstRun == "" || got.PublicAddr != n.PublicAddr || pending || view.Observed.FallbackFollowIPv4.ConfirmedAt != 0 {
				t.Fatal("first sample applied without confirmation")
			}
		case 1:
			if sample.FallbackIPv4.RunID != firstRun || got.PublicAddr != sample.FallbackIPv4.Address || !pending || view.Observed.FallbackFollowIPv4.ConfirmedAt == 0 {
				t.Fatalf("driver continuation failed confirmation: %+v", view)
			}
			lastAddress = got.PublicAddr
			must(s.FinishAddressDNS(ctx, n.ID))
		case 2:
			if sample.FallbackIPv4.CheckStatus != agentproto.PublicAddressFallbackCheckConflict || got.PublicAddr != lastAddress || pending || view.Observed.FallbackFollowIPv4.ConfirmedAt != 0 {
				t.Fatalf("conflict did not suspend following: %+v", view)
			}
		case 3:
			if sample.FallbackIPv4.RunID == firstRun || sample.FallbackIPv4.RunID == "" || got.PublicAddr != lastAddress || pending || view.Observed.FallbackFollowIPv4.ConfirmedAt != 0 {
				t.Fatal("interrupted run inherited old confirmation")
			}
		case 4:
			if sample.FallbackIPv4.RunID != reports[3].PublicAddresses.FallbackIPv4.RunID || got.PublicAddr != sample.FallbackIPv4.Address || view.Observed.FallbackFollowIPv4.ConfirmedAt == 0 {
				t.Fatalf("new driver run failed confirmation: %+v", view)
			}
		}
		must(s.ObserveNodeAddresses(ctx, n.ID, "wire-contract-token", sample, at.Add(10*time.Second)))
		replayed, err := s.NodeAddresses(ctx, n.ID)
		must(err)
		if replayed.Observed.ReceivedAt != view.Observed.ReceivedAt {
			t.Fatal("replayed wire report renewed evidence")
		}
	}
}
